with cleaned as (select id, brand, cost, stock_qty, launch_date, tags, supplier_id, month(launch_date) as launch_date_month, coalesce(brand, 'OTHER') as brand_filled from products where launch_date > date '2023-09-01' and supplier_id is not null and array_contains(tags, 'new')) select case when cost >= 680 then 'HIGH' else 'LOW' end as cost_tier, sum(case when brand = 'Stark' then stock_qty else 0 end) as stark_stock_qty, corr(cost, stock_qty) as corr_cost_stock_qty, sum(case when brand = 'Globex' then stock_qty else 0 end) as globex_stock_qty from cleaned group by case when cost >= 680 then 'HIGH' else 'LOW' end
